import ast, copy, hashlib, json, sys
from pathlib import Path
R=Path.cwd(); sys.path.insert(0,str(R)); O=R/'.local/ri-increments-20261023'
from experiments.increment_25.task_population import _normalized_task_wording
from experiments.increment_25.confirmation_judgments import freeze_confirmation_judgments,evaluate_confirmation,_digest
from experiments.increment_28.import_use import _span
from experiments.increment_36.mechanics import _ranked_case
from experiments.purpose_relative_admission.validation_execution import artifact_envelope
out={}
out['normalization']={s:_normalized_task_wording(s,'') for s in ['added evidence','additional evidence','Fix observation','supported sources','enablement behavior']}
assert out['normalization']['added evidence']=='ed evidence'
freeze=json.loads((R/'experiments/increment_25/task_population_freeze.json').read_text(encoding='utf-8'))
out['retained_truncated_cards']=[{k:r[k] for k in ('case_id','source_commit_sha','parent_snapshot_sha','original_subject','information_need_purpose','lexical_query')} for r in freeze['payload']['task_cards'] if r['original_subject']=='added evidence']
assert len(out['retained_truncated_cards'])==1
b={'schema':'independent-audit-fixture','execution_identity':'audit-only','cases':[{'case_id':'audit','task':{'purpose':'inspect alpha'},'resources':[{'address':'alpha.py','content':'alpha'},{'address':'beta.py','content':'beta'}]}]}
d={'audit':{'alpha.py':{'judgment':'useful','rationale':'independent synthetic positive'},'beta.py':{'judgment':'not-useful','rationale':'independent synthetic negative'}}}
c={'cases':[{'case_id':'audit','capacity':{'m':1,'lexical_exhausted':False},'structural_additions':[{'address':'alpha.py','positive_lexical_rank':None}],'matched_lexical_additions':['beta.py'],'resolution_diagnostics':{}}]}
f,m=freeze_confirmation_judgments(blinded=b,decisions=d)
before=evaluate_confirmation(candidates=c,blinded=b,frozen=f,mapping=m)
swapped=copy.deepcopy(m);rows=swapped['payload']['cases'][0]['mappings'];rows[0]['address'],rows[1]['address']=rows[1]['address'],rows[0]['address']
swapped=artifact_envelope(schema=swapped['schema'],payload=swapped['payload'])
after=evaluate_confirmation(candidates=c,blinded=b,frozen=f,mapping=swapped)
out['increment25_resealed_swap']={'accepted':True,'frozen_judgment_identity_unchanged':f['content_identity'],'before':before['payload']['cases'][0]['judgments_by_arm'],'after':after['payload']['cases'][0]['judgments_by_arm']}
assert out['increment25_resealed_swap']['before']!=out['increment25_resealed_swap']['after']
root=R/'experiments/increment_25';original=json.loads((root/'confirmation_judgment_input.json').read_bytes());mapping=json.loads((root/'confirmation_neutral_mapping.json').read_bytes())
identity=_digest(original);checked=0;mismatches=[]
for bc,mc in zip(original['cases'],mapping['payload']['cases'],strict=True):
 assert bc['case_id']==mc['case_id']
 assert [r['address'] for r in bc['resources']]==[r['address'] for r in mc['mappings']]
 for r in mc['mappings']:
  expected='resource-'+hashlib.sha256(f"{identity}|{bc['case_id']}|{r['address']}".encode()).hexdigest()[:16]
  if r['neutral_id']!=expected:mismatches.append({'case':bc['case_id'],'address':r['address'],'recorded':r['neutral_id'],'expected':expected})
  checked+=1
out['original25_pair_consistency']={'pairs':checked,'computed_package_identity':identity,'declared_package_identity':mapping['payload']['blinded_package_identity'],'mismatches':mismatches,'qualification':'current retained files against current producer rule; original-version compatibility needs Git-object authentication, not new adjudication'}
assert checked==51
assert identity==mapping['payload']['blinded_package_identity'] and not mismatches
out['experimental_span']=[]
for sep in ['\v','\f','\x1c','\x1d','\x1e','\x85','\u2028','\u2029']:
 text='s="a'+sep+'b"\nfrom pkg import f\nx=f()\n'; node=ast.parse(text).body[-1].value.func
 start,end,span=_span(text,node)
 out['experimental_span'].append({'separator':f'U+{ord(sep):04X}','actual':text[start:end],'expected':ast.get_source_segment(text,node),'span':span})
assert all(x['actual']!=x['expected'] for x in out['experimental_span'])
basis={'case_id':'audit','parent_snapshot_sha':'p','information_need':{'purpose':'audit','lexical_query':'q'}}
lex={'case_id':'audit','parent_snapshot_sha':'p','query_text':'q','corpus_id':'c','corpus_resource_count':7,'rankings':{'rrf':[{'address':f'{i}.py','rank':i} for i in range(1,6)]}}
one=_ranked_case(lexical=lex,basis=basis,dense=None)
assert one['selected_top_five']==[f'{i}.py' for i in range(1,6)]
dense={'case_id':'audit','parent_snapshot_sha':'p','information_need':basis['information_need'],'corpus':{'corpus_id':'c','resource_count':7},'semantic_candidates':[{'address':'dense.py'}]}
two=_ranked_case(lexical=lex,basis=basis,dense=dense)
assert two['ranking'][0]['address']=='1.py' and two['ranking'][1]['address']=='dense.py'
out['ranked_only_fusion']={'absent_dense_order':one['selected_top_five'],'tie_order':[r['address'] for r in two['ranking'][:2]],'score':two['ranking'][0]['score']}
try:
 bad=copy.deepcopy(dense);bad['corpus']['corpus_id']='foreign';_ranked_case(lexical=lex,basis=basis,dense=bad)
except ValueError as e:out['foreign_dense_rejected']=str(e)
else:raise AssertionError('foreign dense accepted')
out['checks_passed']=6
(O/'probes.json').write_text(json.dumps(out,indent=2,ensure_ascii=True)+'\n',encoding='utf-8')
print(json.dumps(out,indent=2,ensure_ascii=True))

