import asyncio,hashlib,json,sys
from pathlib import Path
R=Path.cwd();sys.path.insert(0,str(R));O=R/'.local/ri-increments-20261023'
from devtools.core.paths import resolve_path
from devtools.resources.commands import Command,CommandExecutor,CommandOutputPolicy
async def git(*args):
 r=await CommandExecutor(output_policy=CommandOutputPolicy(max_stdout_bytes=8<<20)).execute(Command('git').args(*args).cwd(resolve_path(R)));assert not r.failed and not r.stdout_truncated;return r.stdout
async def main():
 tip=(await git('rev-parse','3994f26d')).decode().strip();out={'origin':tip,'artifacts':{},'serialization_matches':[]}
 for name in ['confirmation_judgment_input.json','confirmation_neutral_mapping.json','confirmation_frozen_judgments.json','confirmation_candidate_evidence.json','confirmation_judgments.py']:
  p='experiments/increment_25/'+name;old=await git('show',tip+':'+p);now=await git('show','HEAD:'+p)
  out['artifacts'][p]={'origin_blob':(await git('rev-parse',tip+':'+p)).decode().strip(),'current_blob':(await git('rev-parse','HEAD:'+p)).decode().strip(),'origin_sha256':hashlib.sha256(old).hexdigest(),'same_git_bytes':old==now}
 b=json.loads(await git('show',tip+':experiments/increment_25/confirmation_judgment_input.json'));m=json.loads(await git('show',tip+':experiments/increment_25/confirmation_neutral_mapping.json'))
 declared=m['payload']['blinded_package_identity'];pairs=[(c['case_id'],r) for c in m['payload']['cases'] for r in c['mappings']]
 out['declared_seed_pairs_agree']=sum(r['neutral_id']=='resource-'+hashlib.sha256(f"{declared}|{case}|{r['address']}".encode()).hexdigest()[:16] for case,r in pairs)
 for indent in [None,2]:
  for ensure in [True,False]:
   for compact in [True,False]:
    text=json.dumps(b,sort_keys=True,indent=indent,ensure_ascii=ensure,**({'separators':(',',':')} if compact else {}))
    for end in ['', '\n']:
     digest=hashlib.sha256((text+end).encode()).hexdigest()
     if digest==declared:out['serialization_matches'].append({'indent':indent,'ensure_ascii':ensure,'compact':compact,'newline':bool(end)})
 print(json.dumps(out,indent=2));(O/'binding-history.json').write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8')
asyncio.run(main())
